// Try to programmatically interact with the dialog on the iOS Simulator
// Using Core Graphics to send keyboard events

int main() {
    // Send a keyboard event simulating the Tab key followed by Return
    // This attempts to move focus to the Open button and activate it

    CGEventRef eventRef;

    // Try pressing Tab to move focus
    eventRef = CGEventCreateKeyboardEvent(NULL, 48, true);  // Tab is key code 48
    if (eventRef) {
        CGEventPost(kCGHIDEventTap, eventRef);
        CFRelease(eventRef);
    }

    usleep(100000);  // 100ms delay

    // Press Return to activate the button (key code 36 for Return)
    eventRef = CGEventCreateKeyboardEvent(NULL, 36, true);
    if (eventRef) {
        CGEventPost(kCGHIDEventTap, eventRef);
        CFRelease(eventRef);
    }

    fprintf(stderr, "Keyboard events sent\n");
    return 0;
}
