        kCGNullWindowID
    ));

    for (NSDictionary *window in windows) {
        NSString *windowName = window[(NSString *)kCGWindowName];
        NSNumber *windowId = window[(NSString *)kCGWindowNumber];
        NSString *appName = window[(NSString *)kCGWindowOwnerName];

